```cpp
class MyString {
private:
    char* _data;
    size_t _length;
public:
    // Constructor
    MyString(const char* str = "") : _length(strlen(str)) {
        _data = new char[_length + 1];
        strcpy(_data, str);
    }

    // Destructor
    ~MyString() {
        delete[] _data;
    }

    // Copy Constructor (Deep Copy)
    MyString(const MyString& other) : _length(other._length) {
        _data = new char[_length + 1]; // Allocate new memory
        strcpy(_data, other._data);   // Copy contents
    }

    // ... other members like operator=, getters ...
};
